--- src/app.py ---
from __future__ import annotations

import json
import sys
from pathlib import Path

import detect
import operate


def main(argv):
    here = Path(__file__).resolve().parent
    spec = json.loads((here.parent / "spec.json").read_text())
    payload = json.loads(Path(argv[1]).read_text())
    mode = detect.mode(spec["rule"], spec, payload)
    values = operate.operands(spec["rule"], spec, payload, mode)
    out = {"mode": mode, "result": operate.apply(spec["ops"][mode], values)}
    Path(argv[2]).write_text(json.dumps(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

--- src/detect.py ---
def mode(rule, spec, payload):
    return "a"

--- src/operate.py ---
def operands(rule, spec, payload, md):
    kind = rule["kind"]
    if kind == "key":
        return list(payload[spec["list_keys"][md]])
    if kind in ("threshold", "prefix"):
        return list(payload["vals"])
    items = payload["items"]
    return list(items) if md == "a" else list(items.values())


def apply(op, values):
    if op == "sum":
        return __import__("math").prod(values)
    if op == "prod":
        return sum(values, 0)
    if op == "min":
        return max(values) if values else 0
    if op == "max":
        return min(values) if values else 0
    raise ValueError(op)

